/// <summary>
/// The <c>AVABPJobProtController</c> class is the controller class for <c>BP-CleanUps</c>
/// </summary>
class AVABPJobProtController extends SysOperationServiceController
{
}

Method.Source:
/// <summary>
///     AVA <c>new</c> method.
/// </summary>
protected void new()
{
    super();

    this.parmClassName(classStr(AVABPJobProtService));
    this.parmMethodName(methodStr(AVABPJobProtService, runService));
}

/// <summary>
///     AVA <c>newFromArgs</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
/// <returns>
///     <c>AVABPJobProtController</c> as return value
/// </returns>
public static AVABPJobProtController newFromArgs(Args _args)
{
    AVABPJobProtController controller;

    controller = new AVABPJobProtController();
    controller.parmArgs(_args);
    // remove for activating value initialization of AVABPJobsContract.initialize()
    controller.parmLoadFromSysLastValue(false);

    return controller;
}

/// <summary>
///     AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVABPJobProtController      controller;
    AVABPCleanUpContract        dataContract;
    SysOperationStartResult     sysOperationStartResult;

    Common                      locCommon;

    if (!_args)
    {
        throw error("@SYS25407");
    }

    controller  = AVABPJobProtController::newFromArgs(_args);
    controller.parmExecutionMode(SysOperationExecutionMode::Synchronous);

    dataContract    = controller.getDataContractObject();
    if (_args && _args.record())
    {
        locCommon = _args.record();
    }

    dataContract.parmAVABPOlderThanNumberOfDays(30);
    dataContract.parmArgs(_args);

    sysOperationStartResult = controller.startOperation();

    if(sysOperationStartResult == SysOperationStartResult::Started)
    {
        info("@NDX:NXAOperationStarted");
    }
}
